format_data:
[
 {
  "fieldname": "print_heading_template",
  "fieldtype": "Custom HTML",
  "options": "
{%- set _afm_logo = (frappe.db.get_value('Company', doc.company, 'company_logo') if doc.company else none) or '/files/afmco-logo-full-1200w.png' -%}
{%- set _afm_k = _('Asset', lang='ar') -%}
<div class="afm afm-lbl" dir="rtl" lang="ar">
  <table>
    <colgroup><col style="width:30mm"><col></colgroup>
    <tr>
      <td class="logo"><img src="{{ _afm_logo }}" alt="AFMCO"></td>
      <td class="id">
        <span class="pair"><span class="ar">{{ _afm_k if _afm_k != 'Asset' else '' }}</span><span class="en ltr">Asset</span></span>
        <span class="v num">{{ doc.name }}</span>
      </td>
    </tr>
  </table>
  <table class="rule"><colgroup><col style="width:22%"><col></colgroup><tr><td class="thick"></td><td class="thin"></td></tr></table>
</div>
"
 },
 {
  "fieldname": "_custom_html",
  "fieldtype": "HTML",
  "label": "Custom HTML",
  "print_hide": 0,
  "options": "<style>

.print-format {
  margin-top: 25mm;
  margin-bottom: 13mm;
  header-spacing: 3;
  margin-left: 15mm;
  margin-right: 15mm;
}

html body, body[onload] { padding: 0 !important; margin: 0 !important; }
html body .print-format, body .print-format { margin: 0 !important; padding: 0 !important; min-height: 0 !important; }
.print-format, .print-format div, .print-format td, .print-format span, .print-format p {
  font-family: "Noto Sans Arabic", "Noto Sans", "DejaVu Sans", sans-serif !important;
  color: #171717;
}
.print-format .en, .print-format .num, .print-format .ltr {
  font-family: "Noto Sans", "DejaVu Sans", sans-serif !important;
}
.afm-lbl { direction: rtl; -webkit-print-color-adjust: exact; }
.afm-lbl table { width: 100%; border-collapse: collapse; table-layout: fixed; margin: 0; }
.print-format .afm-lbl td { padding: 0 !important; border: 0; vertical-align: bottom !important; }
.afm-lbl .logo img { height: 48px; width: auto; display: block; }
.afm-lbl .id { text-align: left; white-space: nowrap; }
.afm-lbl .pair { display: table; margin: 0 auto 0 0; white-space: nowrap; }
.afm-lbl .pair .ar, .afm-lbl .pair .en { display: table-cell; vertical-align: baseline; white-space: nowrap; color: #5f5f5f; }
.afm-lbl .pair .ar { font-size: 7pt; line-height: 12px; padding: 0 0 0 4px; }
.afm-lbl .pair .en { font-size: 6pt; line-height: 10px; direction: ltr; }
.afm-lbl .v { display: block; direction: ltr; text-align: left; font-size: 13pt; line-height: 20px; font-weight: bold; color: #171717; white-space: nowrap; }
.afm-lbl .rule td { height: 8px; }
.afm-lbl .rule .thin { border-bottom: 0.75pt solid #00844e; }
.afm-lbl .rule .thick { border-bottom: 2.4pt solid #00844e; }
.print-format .page-number, .page-number, .print-format .page-number span, .page-number span { font-family: "Noto Sans", "DejaVu Sans", sans-serif !important; font-size: 7pt; line-height: 12px; color: #5f5f5f; }
</style>"
 }
]
